function interSendDeltas(transfers: SigilTransfer[]): number[] {
  if (transfers.length < 2) return [];
  const deltas: number[] = [];
  for (let i = 1; i < transfers.length; i++) {
    const a = transfers[i - 1]!.senderKaiPulse;
    const b = transfers[i]!.senderKaiPulse;
    if (Number.isFinite(a) && Number.isFinite(b) && b >= a) deltas.push(b - a);
  }
  return deltas;
}
function cadenceRegularity01(deltas: number[]): number {
  if (deltas.length === 0) return 1.0;
  const m = median(deltas) || 1;
  let sum = 0;
  for (const d of deltas) sum += Math.abs(d - m) / m;
  const madNorm = sum / deltas.length;
  return 1 / (1 + madNorm);
}

/* present value of intrinsic IP in Φ; supports legacy KS alias */
function presentValueIP(ip: SigilMetadataLite["ip"], nowPulse: number, trace?: CalculationRecorder): number {
  const cfPhi = ip?.expectedCashflowPhi?.map((c, index) => ({ atPulse: c.atPulse, amount: c.amountPhi, id: `ip.phi.${index}` })) ?? [];
  const cfKS  = ip?.expectedCashflowKS?.map((c, index) => ({ atPulse: c.atPulse, amount: c.amountKS, id: `ip.ks.${index}` })) ?? [];
  const cf = [...cfPhi, ...cfKS];
  return cf.reduce((s, c) => {
    const dp = c.atPulse - nowPulse;
    const disc = 1 / (1 + Math.max(0, dp) / DISCOUNT_PULSE_HALFSPAN);
    const contribution = c.amount * disc;
    recordCalculation(trace, `${c.id}.delay`, "Cashflow pulse delay", "atPulse - evaluationPulse", { atPulse: c.atPulse, evaluationPulse: nowPulse }, dp, "pulses", [`metadata.${c.id}`, "app/utils/valuation.ts#presentValueIP"]);
    recordCalculation(trace, `${c.id}.discount`, "Cashflow discount", "1 / (1 + max(0, delay) / DISCOUNT_PULSE_HALFSPAN)", { delay: dp, DISCOUNT_PULSE_HALFSPAN }, disc, "factor", [`metadata.${c.id}`, "policy.DISCOUNT_PULSE_HALFSPAN"]);
    recordCalculation(trace, `${c.id}.presentValue`, "Cashflow present value", "amount * discount", { amount: c.amount, discount: disc }, contribution, "Φ", [`metadata.${c.id}`, "app/utils/valuation.ts#presentValueIP"]);
    return s + contribution;
  }, 0);
}

/* φ-resonance (0.5 neutral, 1 peak aligned) */
function phiResonance01(f?: number, trace?: CalculationRecorder): number {
  if (!f || !Number.isFinite(f) || f <= 0) {
    recordCalculation(trace, "resonance.neutral", "Legacy missing-frequency resonance", "missing, nonfinite, zero or negative frequency => 0.5", { frequencyHz: f }, 0.5, "ratio", ["metadata.frequencyHz", "app/utils/valuation.ts#phiResonance01"]);
    return 0.5;
  }
  const x = Math.log(f) / Math.log(PHI);
  const dist = Math.abs(x - Math.round(x));
  const closeness = clamp(1 - 2 * dist, 0, 1);
  recordCalculation(trace, "resonance.logPhi", "Frequency phi logarithm", "log(frequencyHz)/log(PHI)", { frequencyHz: f, PHI }, x);
  recordCalculation(trace, "resonance.distance", "Nearest phi-power distance", "abs(logPhi-round(logPhi))", { logPhi: x, nearestInteger: Math.round(x) }, dist);
  recordCalculation(trace, "resonance.closeness", "Phi-power closeness", "clamp(1-2*distance,0,1)", { distance: dist }, closeness, "ratio");
  return 0.5 + 0.5 * closeness;
}
function isPrime(n?: number): boolean {
  if (typeof n !== "number" || !Number.isFinite(n) || n < 2) return false;
  const k = Math.floor(n);
  if (k % 2 === 0) return k === 2;
  for (let i = 3; i * i <= k; i += 2) if (k % i === 0) return false;
  return true;
}

/* geometric rarity: tiny, principled lifts */
function geometryLift(meta: SigilMetadataLite, stepsPerBeat: number, resonancePhi: number, trace?: CalculationRecorder): number {
  let lift = 1.0;
  const isEdge =
    typeof meta.stepIndex === "number" &&
    (meta.stepIndex === 0 || meta.stepIndex === (stepsPerBeat > 0 ? stepsPerBeat - 1 : -1));
  const edgeFactor = isEdge ? 1 + GEOM_EDGE_GAIN : 1;
  recordCalculation(trace, "geometry.edgeFactor", "Step edge factor", "isEdge ? 1 + GEOM_EDGE_GAIN : 1", { stepIndex: meta.stepIndex, stepsPerBeat, isEdge, GEOM_EDGE_GAIN }, edgeFactor);
  if (isEdge) lift *= edgeFactor;
  const primeBeat = isPrime(meta.beat);
  const primeFactor = primeBeat ? 1 + GEOM_PRIME_GAIN : 1;
  recordCalculation(trace, "geometry.primeFactor", "Prime beat factor", "isPrime(beat) ? 1 + GEOM_PRIME_GAIN : 1", { beat: meta.beat, primeBeat, GEOM_PRIME_GAIN }, primeFactor);
  if (primeBeat) lift *= primeFactor;
  if (resonancePhi > 0.9) {
    const t = (resonancePhi - 0.9) / 0.1;
    const factor = 1 + GEOM_PHI_GAIN * clamp(t, 0, 1);
    recordCalculation(trace, "geometry.resonanceFactor", "Geometry resonance factor", "1 + GEOM_PHI_GAIN * clamp((resonancePhi - 0.9) / 0.1, 0, 1)", { resonancePhi, t, GEOM_PHI_GAIN }, factor);
    lift *= factor;
  } else {
    recordCalculation(trace, "geometry.resonanceFactor", "Geometry resonance factor", "resonancePhi <= 0.9 => 1", { resonancePhi, GEOM_PHI_GAIN }, 1);
  }
  return lift;
}

