// BigInt sqrt helpers
function bigintSqrt(n: bigint): bigint {
  if (n < 0n) throw new Error("sqrt of negative");
  if (n < 2n) return n;
  let x0 = n, x1 = (n >> 1n) + 1n;
  while (x1 < x0) { x0 = x1; x1 = (x1 + n / x1) >> 1n; }
  return x0;
}
function isPerfectSquareBig(n: bigint): boolean {
  if (n < 0n) return false;
  const r = bigintSqrt(n);
  return r * r === n;
}
// Add near your other module-level state:
const __fibMemo = new Map<number, boolean>();

function isFibonacciExact(pulse: number): boolean {
  if (!Number.isFinite(pulse) || pulse < 0) return false;
  const nSafe = Math.trunc(Math.abs(pulse));
  const cached = __fibMemo.get(nSafe);
  if (cached !== undefined) return cached;

  const n = BigInt(nSafe);
  const a = 5n * n * n + 4n;
  const b = 5n * n * n - 4n;
  const ok = isPerfectSquareBig(a) || isPerfectSquareBig(b);
  setBoundedMemo(__fibMemo, nSafe, ok);
  return ok;
}

// Add near the Fibonacci memo:
const __lucMemo = new Map<number, boolean>();

function isLucasExact(pulse: number): boolean {
  if (!Number.isFinite(pulse) || pulse < 0) return false;
  const nSafe = Math.trunc(Math.abs(pulse));
  const cached = __lucMemo.get(nSafe);
  if (cached !== undefined) return cached;

  const n = BigInt(nSafe);
  let a = 2n, b = 1n;
  while (b < n) { const t = a + b; a = b; b = t; }
  const ok = (b === n);
  setBoundedMemo(__lucMemo, nSafe, ok);
  return ok;
}


function absDigits(pulse: number): string {
  return Math.abs(Math.trunc(pulse)).toString();
}
function allSameDigit(s: string): boolean {
  if (s.length <= 1) return false;
  for (let i = 1; i < s.length; i++) if (s[i] !== s[0]) return false;
  return true;
}
function isPalindromeDigits(s: string): boolean {
  if (s.length <= 1) return false;
  for (let i = 0, j = s.length - 1; i < j; i++, j--) if (s[i] !== s[j]) return false;
  return true;
}
function longestRunSameDigit(s: string): number {
  if (s.length === 0) return 0;
  let max = 1, cur = 1;
  for (let i = 1; i < s.length; i++) {
    if (s[i] === s[i - 1]) { cur++; if (cur > max) max = cur; }
    else cur = 1;
  }
  return max;
}
function longestRunDigitInfo(s: string): { len: number; digit: string } {
  if (s.length === 0) return { len: 0, digit: "" };
  let maxLen = 1, curLen = 1, digit = s[0]!, curDigit = s[0]!;
  for (let i = 1; i < s.length; i++) {
    if (s[i] === s[i - 1]) { curLen++; curDigit = s[i]!; if (curLen > maxLen) { maxLen = curLen; digit = curDigit; } }
    else { curLen = 1; curDigit = s[i]!; }
  }
  return { len: maxLen, digit };
}
function longestConsecutiveSequenceLen(s: string): number {
  if (s.length <= 1) return 1;
  let maxLen = 1, curLen = 1, dir = 0;
  for (let i = 1; i < s.length; i++) {
    const prev = s.charCodeAt(i - 1) - 48;
    const curr = s.charCodeAt(i) - 48;
    const step = curr - prev;
    if (step === dir && (step === 1 || step === -1)) curLen++;
    else if (step === 1 || step === -1) { dir = step; curLen = 2; }
    else { dir = 0; curLen = 1; }
    if (curLen > maxLen) maxLen = curLen;
  }
  return maxLen;
}
function digitEntropy01(s: string, trace?: CalculationRecorder, prefix = "digitEntropy"): number {
  if (s.length === 0) return 1;
  const cnt = Array(10).fill(0);
  for (const ch of s) cnt[ch.charCodeAt(0) - 48]++;
  let H = 0;
  for (let digit = 0; digit < cnt.length; digit++) {
    const c = cnt[digit];
    if (c) {
      const p = c / s.length;
      const term = p * Math.log(p);
      H -= term;
      recordCalculation(trace, `${prefix}.digit.${digit}`, "Digit entropy contribution", "-probability*log(probability)", { digit, count: c, digitCount: s.length, probability: p }, -term, "entropy", ["app/utils/valuation.ts#digitEntropy01"]);
    }
  }
  const Hmax = Math.log(Math.min(10, s.length));
  const result = clamp(H / (Hmax || 1), 0, 1);
  recordCalculation(trace, prefix, "Normalized digit entropy", "clamp(H/(log(min(10,digitCount))||1),0,1)", { digits: s, digitCounts: cnt, H, Hmax, denominator: Hmax || 1 }, result, "ratio", ["app/utils/valuation.ts#digitEntropy01"]);
  return result;
}

// Gentle Genesis proximity lift/discount
function genesisProximityLift(claimPulse: number): number {
  if (!Number.isFinite(claimPulse) || claimPulse < 0) return 1.0;
  const t = claimPulse / (claimPulse + YEAR_PULSES_APPROX);
  return 1 + GENESIS_BIAS_GAIN * (1 - 2 * t);
}

/* φ-spiral transition membership:
   EXACT transition integers s_n = ceil(φ^n), n ≥ 1. Only these pulses qualify. */
// Add near the other memos:
const __phiTransMemo = new Map<number, number | null>();

function phiTransitionIndexFromPulse(pulse: number): number | null {
  if (!Number.isFinite(pulse) || pulse < 1) return null;
  const nSafe = Math.trunc(pulse);
  const cached = __phiTransMemo.get(nSafe);
  if (cached !== undefined) return cached;

  const N = nSafe;
  const nApprox = Math.log(N) / Math.log(PHI);
  const start = Math.max(1, Math.floor(nApprox) - 2);
  let hit: number | null = null;
  for (let k = start; k <= start + 6; k++) {
    const s = Math.ceil(Math.pow(PHI, k));
    if (s === N) { hit = k; break; }
  }
  setBoundedMemo(__phiTransMemo, nSafe, hit);
  return hit;
}


/* Moment rarity (deterministic, multiplicative) */
function momentRarityLiftFromPulse(pulse: number, trace?: CalculationRecorder, prefix = "moment"): number {
  if (!Number.isFinite(pulse) || pulse < 0) {
    recordCalculation(trace, `${prefix}.unsupported`, "Legacy numeric moment neutral factor", "nonfinite or negative pulse => 1", { pulse }, 1);
    return 1.0;
  }
  const s = absDigits(pulse), len = s.length;
  let lift = 1.0;
  const fib = isFibonacciExact(pulse), lucas = isLucasExact(pulse);
  const phiTransition = phiTransitionIndexFromPulse(pulse);
  const uniform = allSameDigit(s), palindrome = isPalindromeDigits(s);
  const fibFactor = fib ? 1 + MOMENT_FIB_EXACT_GAIN : 1;
  const lucasFactor = lucas ? 1 + MOMENT_LUCAS_EXACT_GAIN : 1;
  const transitionFactor = phiTransition !== null ? 1 + MOMENT_PHI_TRANSITION_GAIN : 1;
  const uniformFactor = uniform ? 1 + MOMENT_UNIFORM_GAIN : 1;
  const palindromeFactor = palindrome ? 1 + MOMENT_PAL_GAIN : 1;
  if (fib) lift *= fibFactor;
  if (lucas) lift *= lucasFactor;
  if (phiTransition !== null) lift *= transitionFactor;
  if (uniform) lift *= uniformFactor;
  if (palindrome) lift *= palindromeFactor;

  const run = longestRunSameDigit(s);
  const runNorm = clamp((run - 2) / Math.max(3, len - 2), 0, 1);
  const runFactor = run >= 3 ? 1 + MOMENT_RUN_GAIN * runNorm : 1;
  if (run >= 3) lift *= runFactor;
  const seq = longestConsecutiveSequenceLen(s);
  const seqNorm = clamp((seq - 3) / Math.max(4, len - 3), 0, 1);
  const seqFactor = seq >= 4 ? 1 + MOMENT_SEQ_GAIN * seqNorm : 1;
  if (seq >= 4) lift *= seqFactor;
  const ent = digitEntropy01(s, trace, `${prefix}.digitEntropy`);
  const entropyFactor = 1 + MOMENT_LOW_ENTROPY_GAIN * (1 - ent);
  lift *= entropyFactor;

  const refs = [`pulse:${pulse}`, "app/utils/valuation.ts#momentRarityLiftFromPulse"];
  recordCalculation(trace, `${prefix}.fibonacci`, "Exact Fibonacci moment factor", "exactFibonacci(pulse) ? 1 + MOMENT_FIB_EXACT_GAIN : 1", { pulse, fib, MOMENT_FIB_EXACT_GAIN }, fibFactor, "factor", refs);
  recordCalculation(trace, `${prefix}.lucas`, "Exact Lucas moment factor", "exactLucas(pulse) ? 1 + MOMENT_LUCAS_EXACT_GAIN : 1", { pulse, lucas, MOMENT_LUCAS_EXACT_GAIN }, lucasFactor, "factor", refs);
  recordCalculation(trace, `${prefix}.phiTransition`, "Exact phi transition moment factor", "pulse == ceil(PHI ** transitionIndex) ? 1 + MOMENT_PHI_TRANSITION_GAIN : 1", { pulse, phiTransition, PHI, MOMENT_PHI_TRANSITION_GAIN }, transitionFactor, "factor", refs);
  recordCalculation(trace, `${prefix}.uniform`, "Uniform digit moment factor", "uniform(digits) ? 1 + MOMENT_UNIFORM_GAIN : 1", { digits: s, uniform, MOMENT_UNIFORM_GAIN }, uniformFactor, "factor", refs);
  recordCalculation(trace, `${prefix}.palindrome`, "Palindrome moment factor", "palindrome(digits) ? 1 + MOMENT_PAL_GAIN : 1", { digits: s, palindrome, MOMENT_PAL_GAIN }, palindromeFactor, "factor", refs);
  recordCalculation(trace, `${prefix}.run`, "Repeated digit moment factor", "run >= 3 ? 1 + MOMENT_RUN_GAIN * clamp((run - 2) / max(3, digitCount - 2), 0, 1) : 1", { digits: s, run, digitCount: len, runNorm, MOMENT_RUN_GAIN }, runFactor, "factor", refs);
  recordCalculation(trace, `${prefix}.sequence`, "Consecutive digit moment factor", "sequenceLength >= 4 ? 1 + MOMENT_SEQ_GAIN * clamp((sequenceLength - 3) / max(4, digitCount - 3), 0, 1) : 1", { digits: s, sequenceLength: seq, digitCount: len, seqNorm, MOMENT_SEQ_GAIN }, seqFactor, "factor", refs);
  recordCalculation(trace, `${prefix}.entropy`, "Digit entropy moment factor", "1 + MOMENT_LOW_ENTROPY_GAIN * (1 - digitEntropy01)", { digits: s, digitEntropy01: ent, MOMENT_LOW_ENTROPY_GAIN }, entropyFactor, "factor", refs);
  recordCalculation(trace, `${prefix}.product`, "Numeric moment product", "fibonacci * lucas * phiTransition * uniform * palindrome * run * sequence * entropy", { fibFactor, lucasFactor, transitionFactor, uniformFactor, palindromeFactor, runFactor, seqFactor, entropyFactor }, lift, "factor", refs);
  return lift;
}

/* rarity score in [0..1] (for adoption exponent shaping) — unchanged.
   (φ-spiral transition does NOT affect this shaping signal.) */
function momentRarityScore01FromPulse(pulse: number, trace?: CalculationRecorder, prefix = "rarityScore"): number {
  if (!Number.isFinite(pulse) || pulse < 0) {
    recordCalculation(trace, prefix, "Legacy invalid-coordinate rarity score", "nonfinite or negative pulse => 0", { pulse }, 0, "ratio");
    return 0;
  }
  const s = absDigits(pulse), len = s.length;

  let score = 0, weightSum = 0;

  const fib = isFibonacciExact(pulse) ? 1 : 0;
  score += 1.0 * fib;        weightSum += 1.0;

  const luc = isLucasExact(pulse) ? 1 : 0;
  score += (1 / PHI) * luc;  weightSum += 1 / PHI;

  const uniform = allSameDigit(s) ? 1 : 0;
  score += (1 / PHI) * uniform; weightSum += 1 / PHI;

  const pal = isPalindromeDigits(s) ? 1 : 0;
  score += (1 / PHI ** 2) * pal; weightSum += 1 / PHI ** 2;

  const run = longestRunSameDigit(s);
  const runNorm = clamp((run - 2) / Math.max(3, len - 2), 0, 1);
  score += (1 / PHI ** 2) * runNorm; weightSum += 1 / PHI ** 2;

  const seq = longestConsecutiveSequenceLen(s);
  const seqNorm = clamp((seq - 3) / Math.max(4, len - 3), 0, 1);
  score += (1 / PHI ** 3) * seqNorm; weightSum += 1 / PHI ** 3;

  const ent = digitEntropy01(s, trace, `${prefix}.digitEntropy`);
  score += (1 / PHI ** 3) * (1 - ent); weightSum += 1 / PHI ** 3;

  if (weightSum <= 0) return 0;
  const result = clamp(score / weightSum, 0, 1);
  recordCalculation(trace, prefix, "Weighted numeric rarity score", "clamp((fib + lucas/PHI + uniform/PHI + palindrome/PHI**2 + runNorm/PHI**2 + seqNorm/PHI**3 + (1-entropy)/PHI**3) / weightSum, 0, 1)", { pulse, digits: s, fib, lucas: luc, uniform, palindrome: pal, run, runNorm, seq, seqNorm, entropy: ent, PHI, score, weightSum }, result, "ratio", [`pulse:${pulse}`, "app/utils/valuation.ts#momentRarityScore01FromPulse"]);
  return result;
}

function geometricMean(xs: number[], trace?: CalculationRecorder): number {
  if (!xs.length) return 1.0;
  let sum = 0;
  for (let index = 0; index < xs.length; index++) {
    const x = xs[index]!;
    const term = Math.log(Math.max(x, 1e-12));
    sum += term;
    recordCalculation(trace, `lineage.${index}.logMoment`, "Lineage log moment", "log(max(momentLift,1e-12))", { momentLift: x, minimum: 1e-12 }, term);
  }
  recordCalculation(trace, "lineage.logMean", "Lineage log mean", "sum(logMoments)/closedCount", { sum, closedCount: xs.length }, sum / xs.length);
  return Math.exp(sum / xs.length);
}

/* --------------------- moment affinity primitives --------------------------- */

function circularSim01(a: number, b: number, period: number): number {
  if (!Number.isFinite(a) || !Number.isFinite(b) || period <= 0) return 0.5;
  const da = ((a - b) % period + period) % period;
  const theta = (2 * Math.PI * da) / period;
  return 0.5 * (1 + Math.cos(theta));
}
function stepIndexFromPulse(pulse: number, stepsPerBeat: number): number {
  if (!Number.isFinite(pulse) || stepsPerBeat <= 0) return 0;
  const step = Math.floor(Math.floor(Math.max(0, pulse)) / PULSES_PER_STEP) % stepsPerBeat;
  return step;
}
function breathResidFromPulse(pulse: number): number {
  if (!Number.isFinite(pulse)) return 0;
  return Math.floor(Math.max(0, pulse)) % PULSES_PER_STEP; // 0..10
}
function logPhiFrac01(n: number): number {
  if (!Number.isFinite(n) || n <= 0) return 0;
  const x = Math.log(n) / Math.log(PHI);
  return frac(x);
}
function jaccard01(featuresA: Set<string>, featuresB: Set<string>): number {
  if (featuresA.size === 0 && featuresB.size === 0) return 0;
  const u = new Set([...featuresA, ...featuresB]);
  let inter = 0;
  for (const f of featuresA) if (featuresB.has(f)) inter++;
  return inter / u.size;
}
function motifFeatureSet(pulse: number): Set<string> {
  const s = new Set<string>();
  if (isFibonacciExact(pulse)) s.add("fib");
  if (isLucasExact(pulse))     s.add("lucas");
  const ds = absDigits(pulse);
  if (allSameDigit(ds)) s.add("uniform");
  if (isPalindromeDigits(ds)) s.add("pal");
  if (longestRunSameDigit(ds) >= 4) s.add("longrun");
  if (longestConsecutiveSequenceLen(ds) >= 5) s.add("longseq");
  return s;
}

/* --------------------- φ-adoption compounding primitives -------------------- */
function adoptionIndex01(pulse: number): number {
  if (!Number.isFinite(pulse) || pulse <= 0) return 0;
  return 1 - Math.pow(PHI, -pulse / ADOPTION_TAU_PULSES);
}
function countFibLevelsSince(agePulses: number): number {
  if (!Number.isFinite(agePulses) || agePulses <= 0) return 0;
  let a = 1n, b = 1n, levels = 0;
  const A = BigInt(Math.trunc(agePulses));
  while (b <= A) { levels++; const t = a + b; a = b; b = t; }
  return levels;
}
function countLucasLevelsSince(agePulses: number): number {
  if (!Number.isFinite(agePulses) || agePulses <= 0) return 0;
  let a = 2n, b = 1n, levels = 0;
  const A = BigInt(Math.trunc(agePulses));
  while (b <= A) { levels++; const t = a + b; a = b; b = t; }
  return levels;
}

/* --------------------- φ-Beatty “strobe” (no randomness) -------------------- */
/* Use the irrational rotation by φ to get an equidistributed phase:
   u = frac( (claimPulse + nowPulse) * φ ), strobe = 1 + ε*(2u − 1)
*/
function strobeWave(claimPulse: number, nowPulse: number): { phase01: number; wave: number } {
  const u = frac((claimPulse + nowPulse) * PHI);
  const wave = 1 + STROBE_WAVE_GAIN * (2 * u - 1);
  return { phase01: u, wave };
}

/* --------------------- normalization (single-source step) ------------------- */

function coerceStepsPerBeat(metaSteps?: number): number {
  return Number.isFinite(metaSteps) && (metaSteps as number) > 0
    ? Math.trunc(metaSteps as number)
    : DEFAULT_STEPS_PER_BEAT;
}

function resolveClaimPulse(meta: SigilMetadataLite, nowPulse: number): number {
  return typeof meta.kaiPulse === "number"
    ? meta.kaiPulse
    : typeof meta.pulse === "number"
      ? meta.pulse
      : nowPulse;
}

function resolveStepIndex(meta: SigilMetadataLite, stepsPerBeat: number, claimPulse: number): number {
  if (typeof meta.stepIndex === "number" && Number.isFinite(meta.stepIndex)) {
    return clamp(Math.trunc(meta.stepIndex), 0, stepsPerBeat - 1);
  }
  return stepIndexFromPulse(claimPulse, stepsPerBeat);
}

function resolveBeat(meta: SigilMetadataLite, pulsesPerBeat: number, claimPulse: number): number {
  if (typeof meta.beat === "number" && Number.isFinite(meta.beat)) {
    return Math.trunc(meta.beat);
  }
  return Math.floor(claimPulse / pulsesPerBeat);
}


/* ------------------ NEW: lightweight deep-freeze for cache safety ------------ */
function freezeUnsigned<T extends { inputs: ValueInputs; headRef: ValueSeal["headRef"] }>(u: T): T {
  Object.freeze(u.inputs);
  Object.freeze(u.headRef);
  return Object.freeze(u);
}


/* ------------------ NEW: memo cache for referential stability ---------------- */
export type UnsignedSeal =
  Omit<ValueSeal, "stamp" | "policyChecksum" | "algorithm"> &
  { algorithm: "phi/kosmos-vφ-5"; policyChecksum: string };

const __unsignedCache = new Map<string, UnsignedSeal>();

export type IntrinsicValuationComputation = Readonly<{
  unsigned: UnsignedSeal; stampPayload: string;
  calculation: readonly SigilCalculationTerm[];
  appliedDefaults: readonly ValuationLegacyDefault[];
}>;

function valuationAppliedDefaults(
  meta: SigilMetadataLite, nowPulse: number, steps: number,
  step: number, beat: number, resonance: number
): readonly ValuationLegacyDefault[] {
  const defaults: ValuationLegacyDefault[] = [];
  const add = (field: string, rule: string, value: JSONValue) => {
    if (Array.isArray(value)) Object.freeze(value);
    defaults.push(Object.freeze({ field, rule, value, authority: "reproducibility-only" as const }));
  };
  if (typeof meta.kaiPulse !== "number" && typeof meta.pulse !== "number") add("originPulse", SIGIL_VALUATION_LEGACY_DEFAULTS.originPulse, nowPulse);
  if (!Number.isFinite(meta.stepsPerBeat) || (meta.stepsPerBeat as number) <= 0) add("stepsPerBeat", SIGIL_VALUATION_LEGACY_DEFAULTS.stepsPerBeat, steps);
  if (typeof meta.stepIndex !== "number" || !Number.isFinite(meta.stepIndex)) add("stepIndex", SIGIL_VALUATION_LEGACY_DEFAULTS.stepIndex, step);
  if (typeof meta.beat !== "number" || !Number.isFinite(meta.beat)) add("beat", SIGIL_VALUATION_LEGACY_DEFAULTS.beat, beat);
  if (meta.seriesSize == null) add("seriesSize", "absent => 1", 1);
  if (meta.quality == null) add("quality", "absent => med", "med");
  if (meta.creatorVerified == null) add("creatorVerified", "absent => false (policy default, not a verified identity fact)", false);
  if (meta.creatorRep == null) add("creatorRep", "absent => 0 (policy default, not a reputation observation)", 0);
  if (meta.transfers == null) add("transfers", SIGIL_VALUATION_LEGACY_DEFAULTS.transfers, []);
  if (!meta.frequencyHz || !Number.isFinite(meta.frequencyHz) || meta.frequencyHz <= 0) add("resonancePhi", SIGIL_VALUATION_LEGACY_DEFAULTS.resonancePhi, resonance);
  if (meta.ip?.expectedCashflowPhi == null && meta.ip?.expectedCashflowKS == null) add("ip", SIGIL_VALUATION_LEGACY_DEFAULTS.ip, 0);
  if (meta.cumulativeTransfers == null) add("cumulativeTransfers", SIGIL_VALUATION_LEGACY_DEFAULTS.cumulativeTransfers, meta.transfers?.length ?? 0);
  if (meta.valuationPolicyId == null) add("policyId", SIGIL_VALUATION_LEGACY_DEFAULTS.policyId, null);
  return Object.freeze(defaults);
}

/* -------------------------- intrinsic computation -------------------------- */
export function computeIntrinsicUnsigned(
  meta: SigilMetadataLite,
  nowPulse: number
): IntrinsicValuationComputation {
  const calculation: CalculationRecorder = [];
  // Rhythm derivation (allows alternative stepsPerBeat if provided)
  const STEPS_PER_BEAT = coerceStepsPerBeat(meta.stepsPerBeat);
  const pulsesPerBeat = STEPS_PER_BEAT * PULSES_PER_STEP; // default 484

  const claimPulse = resolveClaimPulse(meta, nowPulse);

  const transfers = meta.transfers ?? [];
  const closed = closedTransfers(transfers);

  const beatsSinceClaim = Math.max(1, (nowPulse - claimPulse) / pulsesPerBeat);
  const velocityPerBeat = transfers.length / beatsSinceClaim;

  // provenance diversity
  const uniqueHolders = distinctReceivers(transfers);

  // closure coherence
  const closedFraction = transfers.length === 0 ? 1 : closed.length / transfers.length;

  // cadence regularity (sender timing)
  const cadenceRegularity = cadenceRegularity01(interSendDeltas(transfers));

  // stewardship (median holds) in beats
  const holdBeats = closed
    .map((t) => (t.receiverKaiPulse! - t.senderKaiPulse) / pulsesPerBeat)
    .filter((x) => x >= 0);
  const medHoldBeats = median(holdBeats);

  // φ-resonance from frequency if present
  const resonancePhi = phiResonance01(meta.frequencyHz, calculation);

  // ---- STEP CONSISTENCY: resolve step & beat once, and use everywhere ----
  const claimStepResolved = resolveStepIndex(meta, STEPS_PER_BEAT, claimPulse);
  const claimBeatResolved = resolveBeat(meta, pulsesPerBeat, claimPulse);
  const metaForGeometry: SigilMetadataLite = {
    ...meta,
    stepIndex: claimStepResolved,
    beat: claimBeatResolved,
  };

  // (optional) geometry lift (uses normalized meta)
  const geomLift = geometryLift(metaForGeometry, STEPS_PER_BEAT, resonancePhi, calculation);

  // age pulses
  const agePulses = Math.max(0, nowPulse - claimPulse);

  // present value of intrinsic cashflows (local IP) in Φ
  const pv_phi = presentValueIP(meta.ip, nowPulse, calculation);

  /* ----------------------------- baseline premium --------------------------- */

  const size = meta.seriesSize ?? 1;
  const rarity = size <= 1 ? RARITY_ONE_OF_ONE : Math.pow(size, -RARITY_EXP);

  const quality = (meta.quality ?? "med") as "low" | "med" | "high";
  const qf = QUALITY_MAP[quality];
  const creator = (meta.creatorVerified ? 1 + CREATOR_VERIFIED_LIFT : 1) + (meta.creatorRep ?? 0) * CREATOR_REP_MAX;

  const prov = 1 + PROV_LOG_SLOPE * log1p(uniqueHolders - 1);

  const closureCentered = clamp((closedFraction - CLOSURE_CENTER) * CLOSURE_RANGE_INV, -1, 1);
  const closureLift = 1 + CLOSURE_GAIN * closureCentered;

  const cadenceLift = 1 + CADENCE_GAIN * (2 * cadenceRegularity - 1);

  const holdLift = clamp(1 + HOLD_SLOPE * log1p(medHoldBeats), 1, HOLD_CAP);

  const resonanceLift = 1 + RESONANCE_GAIN * (2 * resonancePhi - 1);

  const ageBeats = agePulses / pulsesPerBeat;
  const ageLift = Math.min(AGE_CAP, 1 + AGE_EPS * log1p(ageBeats));

  const churnPenalty = 1 / (1 + CHURN_KAPPA * Math.max(0, velocityPerBeat));

  const claimMoment = momentRarityLiftFromPulse(claimPulse, calculation, "claimMoment");
  const lineageMoments = closed
    .map((t, index) => (Number.isFinite(t.receiverKaiPulse) ? momentRarityLiftFromPulse(t.receiverKaiPulse as number, calculation, `lineage.${index}.moment`) : 1));
  const lineageGM = geometricMean(lineageMoments, calculation);
  const genesisBias = genesisProximityLift(claimPulse);
  const momentLift = claimMoment * Math.max(1, lineageGM) * genesisBias;

  const baselinePremium =
    rarity *
    qf *
    creator *
    prov *
    closureLift *
    cadenceLift *
    holdLift *
    resonanceLift *
    ageLift *
    churnPenalty *
    geomLift *
    momentLift;

  /* ------------------------ dynamic φ-compounding & floor -------------------- */

  const adoptionAtClaim = adoptionIndex01(claimPulse);
  const adoptionNow = adoptionIndex01(nowPulse);
  const adoptionDelta = Math.max(0, adoptionNow - adoptionAtClaim);

  const rarityScore01 = momentRarityScore01FromPulse(claimPulse, calculation, "claimRarityScore");
  const k = ADOPTION_GAIN_BASE + ADOPTION_GAIN_RARE * rarityScore01;

  const adoptionLift = Math.exp(k * adoptionDelta);
  const indexScarcity = 1 + INDEX_SCARCITY_GAIN * (1 - adoptionAtClaim);

  const fibLevels   = countFibLevelsSince(agePulses);
  const lucasLevels = countLucasLevelsSince(agePulses);
  const fibAccrualLift   = Math.exp(FIB_STEP_GAIN   * fibLevels);
  const lucasAccrualLift = Math.exp(LUCAS_STEP_GAIN * lucasLevels);

  const dynamicGrowth = indexScarcity * adoptionLift * fibAccrualLift * lucasAccrualLift;

  // Strict monotone rarity floor
  const rarityFloor = 1 * claimMoment * indexScarcity * adoptionLift * fibAccrualLift * lucasAccrualLift * Math.max(1, genesisBias);

  /* --------------------------- live oscillations (φ) ------------------------- */

  // Breath wave
  const breathPhase01 = pulsesPerBeat > 0
    ? quantizeOsc((nowPulse % pulsesPerBeat) / pulsesPerBeat)
    : 0;
  const breathAmp = BREATH_WAVE_GAIN * (0.5 + 0.5 * cadenceRegularity);
  const breathWave = quantizeOsc(1 + breathAmp * Math.sin(2 * Math.PI * breathPhase01));

  // Kai-day wave (claim-day ↔ now-day alignment)
  const dayPhase01 = quantizeOsc(frac(nowPulse / PULSES_PER_DAY_EXACT));
  const claimDayPhase01 = quantizeOsc(frac(claimPulse / PULSES_PER_DAY_EXACT));
  const daySim = 1 - Math.abs(((dayPhase01 - claimDayPhase01 + 1) % 1) - 0.5) * 2;
  const dayAmp = DAY_WAVE_GAIN * (0.5 + 0.5 * resonancePhi) * (0.5 + 0.5 * cadenceRegularity);
  const dayWave = quantizeOsc(1 + dayAmp * (2 * daySim - 1));

  // φ-Beatty strobe (no RNG)
  const { phase01: strobePhaseRaw, wave: strobeWaveRaw } = strobeWave(claimPulse, nowPulse);
  const strobePhase01 = quantizeOsc(strobePhaseRaw);
  const strobeWaveVal = quantizeOsc(strobeWaveRaw);

  // Moment Affinity (use resolved claim step)
  const claimStep = claimStepResolved;
  const nowStep = stepIndexFromPulse(nowPulse, STEPS_PER_BEAT);
  const stepSim = circularSim01(nowStep, claimStep, STEPS_PER_BEAT);

  const claimResid = breathResidFromPulse(claimPulse);
  const nowResid = breathResidFromPulse(nowPulse);
  const breathSim = circularSim01(nowResid, claimResid, PULSES_PER_STEP);

  const phiFracSim = 1 - Math.abs(
    (logPhiFrac01(nowPulse + 1) - logPhiFrac01(claimPulse + 1) + 1) % 1 - 0.5
  ) * 2;

  const claimRareScore = rarityScore01;
  const nowRareScore = momentRarityScore01FromPulse(nowPulse, calculation, "nowRarityScore");
  const rareSim = 1 - Math.abs(claimRareScore - nowRareScore);

  const claimMotifs = motifFeatureSet(claimPulse);
  const nowMotifs = motifFeatureSet(nowPulse);
  const motifSim = jaccard01(claimMotifs, nowMotifs);

  const w_step = 0.30, w_breath = 0.30, w_phi = 0.20, w_digit = 0.20;
  const digitBlend = (MOMENT_AFFINITY_DIGIT_WEIGHT * motifSim + (1 - MOMENT_AFFINITY_DIGIT_WEIGHT) * rareSim);
  const momentAffinitySim01 = quantizeOsc(
    w_step * stepSim + w_breath * breathSim + w_phi * phiFracSim + w_digit * digitBlend
  );

  const momentAffinityAmp = quantizeOsc(
    MOMENT_AFFINITY_GAIN_BASE *
    (0.5 + 0.5 * claimRareScore) *
    (0.5 + 0.5 * resonancePhi)
  );

  const momentAffinityOsc = quantizeOsc(1 + momentAffinityAmp * (2 * momentAffinitySim01 - 1));

  // Combine waves (strictly positive; preserves floor)
  const combinedOsc = quantizeOsc(breathWave * dayWave * strobeWaveVal * momentAffinityOsc);

  /* ----------------------- compose premium with living band ------------------ */

  const premiumPreWave = baselinePremium * dynamicGrowth;
  const premiumBandBase = Math.max(0, premiumPreWave - rarityFloor);
  const premium = rarityFloor + premiumBandBase * combinedOsc;

  // Final value in Φ
  const valuePhi = 1 * premium + pv_phi;

  // The trace observes the operands used above. It is replay data beneath the
  // source proof, never proof, creator, ownership or executed-sale admission.
  recordCalculation(calculation, "sourceMetadata", "Explicit low-level metadata", "caller supplied metadata (reproducibility only)", { metadata: meta }, stableStringify(meta), "reproducibility", ["caller.metadata"]);
  recordCalculation(calculation, "baseUnit", "Coherent breath base unit", "1 coherent breath = 1 Phi", { coherentBreaths: 1 }, 1, "Φ", ["policy.baseUnit"]);
  recordCalculation(calculation, "originPulse", "Resolved creation coordinate", "numeric kaiPulse, else numeric pulse, else explicit evaluationPulse (legacy low-level default)", { kaiPulse: meta.kaiPulse, pulse: meta.pulse, evaluationPulse: nowPulse }, claimPulse, "pulses", ["metadata.kaiPulse", "metadata.pulse", "policy.legacyDefaults.originPulse"]);
  recordCalculation(calculation, "evaluationPulse", "Explicit evaluation coordinate", "evaluationPulse", { evaluationPulse: nowPulse }, nowPulse, "pulses", ["caller.nowPulse"]);
  recordCalculation(calculation, "stepsPerBeat", "Resolved steps per beat", "finite positive supplied stepsPerBeat ? trunc(stepsPerBeat) : 44", { supplied: meta.stepsPerBeat, DEFAULT_STEPS_PER_BEAT }, STEPS_PER_BEAT, "steps/beat");
  recordCalculation(calculation, "pulsesPerBeat", "Pulses per beat", "stepsPerBeat * PULSES_PER_STEP", { stepsPerBeat: STEPS_PER_BEAT, PULSES_PER_STEP }, pulsesPerBeat, "pulses/beat");
  recordCalculation(calculation, "claimStep", "Resolved origin step", "finite supplied stepIndex ? clamp(trunc(stepIndex),0,stepsPerBeat-1) : floor(floor(max(0,claimPulse))/11) % stepsPerBeat", { supplied: meta.stepIndex, claimPulse, stepsPerBeat: STEPS_PER_BEAT, PULSES_PER_STEP }, claimStep, "step");
  recordCalculation(calculation, "claimBeat", "Resolved origin beat", "finite supplied beat ? trunc(beat) : floor(claimPulse/pulsesPerBeat)", { supplied: meta.beat, claimPulse, pulsesPerBeat }, claimBeatResolved, "beat");
  recordCalculation(calculation, "agePulses", "Age at evaluation", "max(0, evaluationPulse - claimPulse)", { evaluationPulse: nowPulse, claimPulse }, agePulses, "pulses");
  recordCalculation(calculation, "beatsSinceClaim", "Velocity denominator", "max(1, (evaluationPulse - claimPulse)/pulsesPerBeat)", { evaluationPulse: nowPulse, claimPulse, pulsesPerBeat }, beatsSinceClaim, "beats");
  recordCalculation(calculation, "velocityPerBeat", "Explicit transfer velocity", "transfers.length / beatsSinceClaim", { transferCount: transfers.length, beatsSinceClaim }, velocityPerBeat, "transfers/beat", ["metadata.transfers", "app/utils/valuation.ts#computeIntrinsicUnsigned"]);
  recordCalculation(calculation, "uniqueHolders", "Explicit receiver diversity", "max(1, distinct truthy receiverSignature count)", { receiverSignatures: transfers.map(t => t.receiverSignature ?? null) }, uniqueHolders, "receivers", ["metadata.transfers", "app/utils/valuation.ts#distinctReceivers"]);
  recordCalculation(calculation, "closedFraction", "Explicit transfer closure fraction", "transfers.length == 0 ? 1 : closed.length/transfers.length", { transferCount: transfers.length, closedCount: closed.length }, closedFraction, "ratio");
  const sendDeltas = interSendDeltas(transfers);
  const sendMedian = median(sendDeltas) || 1;
  const sendMadNorm = sendDeltas.reduce((sum, delta) => sum + Math.abs(delta - sendMedian) / sendMedian, 0) / (sendDeltas.length || 1);
  recordCalculation(calculation, "cadenceRegularity", "Sender cadence regularity", "no deltas ? 1 : 1/(1+mean(abs(delta-(median(deltas)||1))/(median(deltas)||1)))", { sendPulses: transfers.map(t => t.senderKaiPulse), nondecreasingFiniteDeltas: sendDeltas, medianOrOne: sendMedian, madNorm: sendMadNorm }, cadenceRegularity, "ratio", ["metadata.transfers", "app/utils/valuation.ts#cadenceRegularity01"]);
  recordCalculation(calculation, "medianHoldBeats", "Explicit median stewardship", "median(nonnegative((receiverPulse-senderPulse)/pulsesPerBeat) for closed transfers)", { closedTransfers: closed, nonnegativeHoldBeats: holdBeats, pulsesPerBeat }, medHoldBeats, "beats");
  recordCalculation(calculation, "resonancePhi", "Frequency phi resonance", "invalid frequency ? 0.5 : 0.5 + 0.5*clamp(1-2*abs(log(frequency)/log(PHI)-round(log(frequency)/log(PHI))),0,1)", { frequencyHz: meta.frequencyHz, PHI }, resonancePhi, "ratio", ["metadata.frequencyHz", "app/utils/valuation.ts#phiResonance01"]);
  recordCalculation(calculation, "seriesRarity", "Series rarity factor", "size <= 1 ? RARITY_ONE_OF_ONE : pow(size, -RARITY_EXP)", { size, RARITY_ONE_OF_ONE, RARITY_EXP }, rarity);
  recordCalculation(calculation, "qualityFactor", "Craft quality factor", "QUALITY_MAP[quality]", { quality, QUALITY_MAP }, qf);
  recordCalculation(calculation, "creatorFactor", "Explicit creator factor", "(creatorVerified ? 1+CREATOR_VERIFIED_LIFT : 1) + creatorRep*CREATOR_REP_MAX", { creatorVerified: !!meta.creatorVerified, creatorRep: meta.creatorRep ?? 0, CREATOR_VERIFIED_LIFT, CREATOR_REP_MAX }, creator);
  recordCalculation(calculation, "provenanceFactor", "Receiver diversity factor", "1 + PROV_LOG_SLOPE*log(1+max(0,uniqueHolders-1))", { uniqueHolders, PROV_LOG_SLOPE }, prov);
  recordCalculation(calculation, "closureCentered", "Centered closure", "clamp((closedFraction-CLOSURE_CENTER)*CLOSURE_RANGE_INV,-1,1)", { closedFraction, CLOSURE_CENTER, CLOSURE_RANGE_INV }, closureCentered, "ratio");
  recordCalculation(calculation, "closureLift", "Closure factor", "1 + CLOSURE_GAIN*closureCentered", { closureCentered, CLOSURE_GAIN }, closureLift);
  recordCalculation(calculation, "cadenceLift", "Cadence factor", "1 + CADENCE_GAIN*(2*cadenceRegularity-1)", { cadenceRegularity, CADENCE_GAIN }, cadenceLift);
  recordCalculation(calculation, "holdLift", "Stewardship factor", "clamp(1+HOLD_SLOPE*log(1+max(0,medianHoldBeats)),1,HOLD_CAP)", { medianHoldBeats: medHoldBeats, HOLD_SLOPE, HOLD_CAP }, holdLift);
  recordCalculation(calculation, "resonanceLift", "Frequency resonance factor", "1 + RESONANCE_GAIN*(2*resonancePhi-1)", { resonancePhi, RESONANCE_GAIN }, resonanceLift);
  recordCalculation(calculation, "ageBeats", "Age in beats", "agePulses/pulsesPerBeat", { agePulses, pulsesPerBeat }, ageBeats, "beats");
  recordCalculation(calculation, "ageLift", "Capped age factor", "min(AGE_CAP,1+AGE_EPS*log(1+max(0,ageBeats)))", { ageBeats, AGE_CAP, AGE_EPS }, ageLift);
  recordCalculation(calculation, "churnPenalty", "Explicit transfer churn factor", "1/(1+CHURN_KAPPA*max(0,velocityPerBeat))", { velocityPerBeat, CHURN_KAPPA }, churnPenalty);
  recordCalculation(calculation, "geometryLift", "Geometry product", "edgeFactor * primeBeatFactor * geometryResonanceFactor", { claimStep, claimBeat: claimBeatResolved, resonancePhi, GEOM_EDGE_GAIN, GEOM_PRIME_GAIN, GEOM_PHI_GAIN }, geomLift);
  recordCalculation(calculation, "claimMomentLift", "Creation numeric moment factor", "product of exact numeric-set and digit-motif factors", { claimPulse, dependency: "claimMoment.product" }, claimMoment);
  recordCalculation(calculation, "lineageGeometricMean", "Explicit lineage moment mean", "no closed transfers ? 1 : exp(sum(log(max(momentLift,1e-12)))/closedCount)", { lineageMomentLifts: lineageMoments, closedCount: lineageMoments.length }, lineageGM);
  recordCalculation(calculation, "genesisBias", "Genesis proximity factor", "invalid or negative claimPulse ? 1 : 1+GENESIS_BIAS_GAIN*(1-2*claimPulse/(claimPulse+YEAR_PULSES_APPROX))", { claimPulse, GENESIS_BIAS_GAIN, YEAR_PULSES_APPROX }, genesisBias);
  recordCalculation(calculation, "momentLift", "Combined moment factor", "claimMoment * max(1,lineageGM) * genesisBias", { claimMoment, lineageGM, genesisBias }, momentLift);
  recordCalculation(calculation, "baselinePremium", "Baseline premium", "rarity * quality * creator * provenance * closure * cadence * hold * resonance * age * churn * geometry * moment", { rarity, quality: qf, creator, provenance: prov, closure: closureLift, cadence: cadenceLift, hold: holdLift, resonance: resonanceLift, age: ageLift, churn: churnPenalty, geometry: geomLift, moment: momentLift }, baselinePremium, "Φ");
  recordCalculation(calculation, "adoptionAtClaim", "Origin adoption index", "claimPulse <= 0 or nonfinite ? 0 : 1-pow(PHI,-claimPulse/ADOPTION_TAU_PULSES)", { claimPulse, PHI, ADOPTION_TAU_PULSES }, adoptionAtClaim, "ratio");
  recordCalculation(calculation, "adoptionNow", "Evaluation adoption index", "evaluationPulse <= 0 or nonfinite ? 0 : 1-pow(PHI,-evaluationPulse/ADOPTION_TAU_PULSES)", { evaluationPulse: nowPulse, PHI, ADOPTION_TAU_PULSES }, adoptionNow, "ratio");
  recordCalculation(calculation, "adoptionDelta", "Adoption change", "max(0, adoptionNow-adoptionAtClaim)", { adoptionNow, adoptionAtClaim }, adoptionDelta, "ratio");
  recordCalculation(calculation, "adoptionExponent", "Rarity-shaped adoption exponent", "ADOPTION_GAIN_BASE + ADOPTION_GAIN_RARE*rarityScore01", { ADOPTION_GAIN_BASE, ADOPTION_GAIN_RARE, rarityScore01 }, k);
  recordCalculation(calculation, "adoptionLift", "Adoption factor", "exp(adoptionExponent*adoptionDelta)", { adoptionExponent: k, adoptionDelta }, adoptionLift);
  recordCalculation(calculation, "indexScarcity", "Origin adoption scarcity", "1+INDEX_SCARCITY_GAIN*(1-adoptionAtClaim)", { INDEX_SCARCITY_GAIN, adoptionAtClaim }, indexScarcity);
  recordCalculation(calculation, "fibAccrualLevels", "Fibonacci age thresholds", "count Fibonacci b<=trunc(agePulses), starting a=1,b=1", { agePulses }, fibLevels, "levels", ["app/utils/valuation.ts#countFibLevelsSince"]);
  recordCalculation(calculation, "lucasAccrualLevels", "Lucas age thresholds", "count Lucas b<=trunc(agePulses), starting a=2,b=1", { agePulses }, lucasLevels, "levels", ["app/utils/valuation.ts#countLucasLevelsSince"]);
  recordCalculation(calculation, "fibAccrualLift", "Fibonacci accrual factor", "exp(FIB_STEP_GAIN*fibLevels)", { FIB_STEP_GAIN, fibLevels }, fibAccrualLift);
  recordCalculation(calculation, "lucasAccrualLift", "Lucas accrual factor", "exp(LUCAS_STEP_GAIN*lucasLevels)", { LUCAS_STEP_GAIN, lucasLevels }, lucasAccrualLift);
  recordCalculation(calculation, "dynamicGrowth", "Dynamic growth product", "indexScarcity*adoptionLift*fibAccrualLift*lucasAccrualLift", { indexScarcity, adoptionLift, fibAccrualLift, lucasAccrualLift }, dynamicGrowth);
  recordCalculation(calculation, "rarityFloor", "Rarity floor", "1*claimMoment*indexScarcity*adoptionLift*fibAccrualLift*lucasAccrualLift*max(1,genesisBias)", { baseUnit: 1, claimMoment, indexScarcity, adoptionLift, fibAccrualLift, lucasAccrualLift, genesisBias }, rarityFloor, "Φ");
  recordCalculation(calculation, "breathPhase01", "Quantized breath phase", "Q((evaluationPulse%pulsesPerBeat)/pulsesPerBeat)", { evaluationPulse: nowPulse, pulsesPerBeat }, breathPhase01, "phase");
  recordCalculation(calculation, "breathAmplitude", "Breath amplitude", "BREATH_WAVE_GAIN*(0.5+0.5*cadenceRegularity)", { BREATH_WAVE_GAIN, cadenceRegularity }, breathAmp);
  recordCalculation(calculation, "breathWave", "Quantized breath wave", "Q(1+breathAmplitude*sin(2*PI*breathPhase01))", { breathAmplitude: breathAmp, PI: Math.PI, breathPhase01 }, breathWave);
  recordCalculation(calculation, "dayPhase01", "Quantized evaluation day phase", "Q(frac(evaluationPulse/PULSES_PER_DAY_EXACT))", { evaluationPulse: nowPulse, PULSES_PER_DAY_EXACT }, dayPhase01, "phase");
  recordCalculation(calculation, "claimDayPhase01", "Quantized origin day phase", "Q(frac(claimPulse/PULSES_PER_DAY_EXACT))", { claimPulse, PULSES_PER_DAY_EXACT }, claimDayPhase01, "phase");
  recordCalculation(calculation, "daySimilarity", "Day phase similarity", "1-abs(((dayPhase01-claimDayPhase01+1)%1)-0.5)*2", { dayPhase01, claimDayPhase01 }, daySim, "ratio");
  recordCalculation(calculation, "dayAmplitude", "Day amplitude", "DAY_WAVE_GAIN*(0.5+0.5*resonancePhi)*(0.5+0.5*cadenceRegularity)", { DAY_WAVE_GAIN, resonancePhi, cadenceRegularity }, dayAmp);
  recordCalculation(calculation, "dayWave", "Quantized day wave", "Q(1+dayAmplitude*(2*daySimilarity-1))", { dayAmplitude: dayAmp, daySimilarity: daySim }, dayWave);
  recordCalculation(calculation, "strobePhaseRaw", "Beatty phase", "frac((claimPulse+evaluationPulse)*PHI)", { claimPulse, evaluationPulse: nowPulse, PHI }, strobePhaseRaw, "phase");
  recordCalculation(calculation, "strobePhase01", "Quantized Beatty phase", "Q(strobePhaseRaw)", { strobePhaseRaw }, strobePhase01, "phase");
  recordCalculation(calculation, "strobeWaveRaw", "Beatty wave before rounding", "1+STROBE_WAVE_GAIN*(2*strobePhaseRaw-1)", { STROBE_WAVE_GAIN, strobePhaseRaw }, strobeWaveRaw);
  recordCalculation(calculation, "strobeWave", "Quantized Beatty wave", "Q(strobeWaveRaw)", { strobeWaveRaw }, strobeWaveVal);
  recordCalculation(calculation, "affinity.nowStep", "Evaluation step", "floor(floor(max(0,evaluationPulse))/PULSES_PER_STEP)%stepsPerBeat", { evaluationPulse: nowPulse, PULSES_PER_STEP, stepsPerBeat: STEPS_PER_BEAT }, nowStep, "step");
  recordCalculation(calculation, "affinity.claimBreathResidue", "Origin breath residue", "floor(max(0,claimPulse))%PULSES_PER_STEP", { claimPulse, PULSES_PER_STEP }, claimResid, "pulse residue");
  recordCalculation(calculation, "affinity.nowBreathResidue", "Evaluation breath residue", "floor(max(0,evaluationPulse))%PULSES_PER_STEP", { evaluationPulse: nowPulse, PULSES_PER_STEP }, nowResid, "pulse residue");
  recordCalculation(calculation, "affinity.stepSimilarity", "Circular step similarity", "0.5*(1+cos(2*PI*(((nowStep-claimStep)%stepsPerBeat+stepsPerBeat)%stepsPerBeat)/stepsPerBeat))", { nowStep, claimStep, stepsPerBeat: STEPS_PER_BEAT, PI: Math.PI }, stepSim, "ratio");
  recordCalculation(calculation, "affinity.breathSimilarity", "Circular breath residue similarity", "0.5*(1+cos(2*PI*(((nowResid-claimResid)%PULSES_PER_STEP+PULSES_PER_STEP)%PULSES_PER_STEP)/PULSES_PER_STEP))", { nowResid, claimResid, PULSES_PER_STEP, PI: Math.PI }, breathSim, "ratio");
  recordCalculation(calculation, "affinity.phiFractionSimilarity", "Phi fraction similarity", "1-abs((frac(log(evaluationPulse+1)/log(PHI))-frac(log(claimPulse+1)/log(PHI))+1)%1-0.5)*2", { evaluationPulse: nowPulse, claimPulse, PHI, nowPhiFraction: logPhiFrac01(nowPulse+1), claimPhiFraction: logPhiFrac01(claimPulse+1) }, phiFracSim, "ratio");
  recordCalculation(calculation, "affinity.raritySimilarity", "Numeric rarity similarity", "1-abs(claimRareScore-nowRareScore)", { claimRareScore, nowRareScore }, rareSim, "ratio");
  recordCalculation(calculation, "affinity.motifSimilarity", "Exact motif intersection", "no features ? 0 : intersectionCount/unionCount", { claimMotifs: [...claimMotifs], nowMotifs: [...nowMotifs], motifRules: "fib,lucas,uniform,pal,longrun>=4,longseq>=5" }, motifSim, "ratio", ["app/utils/valuation.ts#motifFeatureSet", "app/utils/valuation.ts#jaccard01"]);
  recordCalculation(calculation, "affinity.digitBlend", "Digit and rarity blend", "MOMENT_AFFINITY_DIGIT_WEIGHT*motifSim+(1-MOMENT_AFFINITY_DIGIT_WEIGHT)*rareSim", { MOMENT_AFFINITY_DIGIT_WEIGHT, motifSim, rareSim }, digitBlend, "ratio");
  recordCalculation(calculation, "momentAffinitySim01", "Quantized moment affinity", "Q(w_step*stepSim+w_breath*breathSim+w_phi*phiFracSim+w_digit*digitBlend)", { w_step, stepSim, w_breath, breathSim, w_phi, phiFracSim, w_digit, digitBlend }, momentAffinitySim01, "ratio");
  recordCalculation(calculation, "momentAffinityAmp", "Quantized affinity amplitude", "Q(MOMENT_AFFINITY_GAIN_BASE*(0.5+0.5*claimRareScore)*(0.5+0.5*resonancePhi))", { MOMENT_AFFINITY_GAIN_BASE, claimRareScore, resonancePhi }, momentAffinityAmp);
  recordCalculation(calculation, "momentAffinityOsc", "Quantized affinity wave", "Q(1+momentAffinityAmp*(2*momentAffinitySim01-1))", { momentAffinityAmp, momentAffinitySim01 }, momentAffinityOsc);
  recordCalculation(calculation, "combinedOsc", "Quantized live wave product", "Q(breathWave*dayWave*strobeWave*momentAffinityOsc)", { breathWave, dayWave, strobeWave: strobeWaveVal, momentAffinityOsc }, combinedOsc);
  recordCalculation(calculation, "premiumPreWave", "Premium before waves", "baselinePremium*dynamicGrowth", { baselinePremium, dynamicGrowth }, premiumPreWave, "Φ");
  recordCalculation(calculation, "premiumBandBase", "Nonnegative premium band", "max(0,premiumPreWave-rarityFloor)", { premiumPreWave, rarityFloor }, premiumBandBase, "Φ");
  recordCalculation(calculation, "premium", "Live intrinsic premium", "rarityFloor+premiumBandBase*combinedOsc", { rarityFloor, premiumBandBase, combinedOsc }, premium, "Φ");
  recordCalculation(calculation, "pv_phi", "Intrinsic cashflow present value", "sum(amount*discount for Phi cashflows then legacy KS alias cashflows)", { phiCashflows: meta.ip?.expectedCashflowPhi ?? [], legacyKsCashflows: meta.ip?.expectedCashflowKS ?? [], evaluationPulse: nowPulse, DISCOUNT_PULSE_HALFSPAN }, pv_phi, "Φ");
  recordCalculation(calculation, "valuePhi", "Intrinsic proof valuation", "1*premium+pv_phi", { coherentBreathPhi: 1, premium, pv_phi }, valuePhi, "Φ");
  recordCalculation(calculation, "oscillatorRounding", "Oscillator quantization rule", "Q(x) = finite(x) ? Math.round(x*1000000)/1000000 : 0", { OSC_QUANT }, String(OSC_QUANT), "rounding", ["policy.rounding.oscillator"]);

  const headRef = {
    headHash: undefined as HashHex | undefined,
    transfersWindowRoot: meta.transfersWindowRoot,
    cumulativeTransfers: meta.cumulativeTransfers ?? transfers.length,
  };

  const inputs: ValueInputs = {
    // existing
    size,
    quality,
    creatorVerified: !!meta.creatorVerified,
    creatorRep: meta.creatorRep ?? 0,
    uniqueHolders,
    closedFraction,
    cadenceRegularity,
    medianHoldBeats: medHoldBeats,
    velocityPerBeat,
    resonancePhi,
    pulsesPerBeat,
    agePulses,
    geometryLift: geomLift,
    momentLift,
    pv_phi,

    // growth & rarity diagnostics
    algorithmVersion: "phi/kosmos-vφ-5",
    adoptionAtClaim,
    adoptionNow,
    adoptionDelta,
    rarityScore01,
    fibAccrualLevels: fibLevels,
    lucasAccrualLevels: lucasLevels,
    indexScarcity,
    adoptionLift,
    fibAccrualLift,
    lucasAccrualLift,

    // live moment diagnostics
    breathPhase01,
    breathWave,
    dayPhase01,
    dayWave,
    strobePhase01,
    strobeWave: strobeWaveVal,
    momentAffinitySim01,
    momentAffinityAmp,
    momentAffinityOsc,
    combinedOsc,

    // band/floor
    dynamicGrowth,
    rarityFloor,
    premiumBandBase,
  };

  // ---- use hoisted checksum (unchanged value, stable reference) ----
  const checksum = POLICY_CHECKSUM;

  const unsignedRaw: UnsignedSeal = {
    version: 1 as const,
    unit: "Φ" as const,
    algorithm: "phi/kosmos-vφ-5" as const,
    policyId: meta.valuationPolicyId,
    policyChecksum: checksum,
    valuePhi,
    premium,
    inputs,
    computedAtPulse: nowPulse,
    headRef,
  };

  const stampPayload = stableStringify({
    algorithm: unsignedRaw.algorithm,
    policy: unsignedRaw.policyId ?? null,
    policyChecksum: unsignedRaw.policyChecksum,
    inputs: unsignedRaw.inputs,
    minimalHead: {
      headHash: unsignedRaw.headRef.headHash ?? null,
      transfersWindowRoot: unsignedRaw.headRef.transfersWindowRoot ?? null,
      cumulativeTransfers: unsignedRaw.headRef.cumulativeTransfers,
    },
  });

  // ---- MEMOIZATION for referential stability (prevents render loops) ----
  const cacheKey = stampPayload + ":evaluation:" + (Object.is(nowPulse, -0) ? "-0" : String(nowPulse));
  const appliedDefaults = valuationAppliedDefaults(meta, nowPulse, STEPS_PER_BEAT, claimStepResolved, claimBeatResolved, resonancePhi);
  const immutableCalculation = Object.freeze(calculation);
  const cached = __unsignedCache.get(cacheKey);
  if (cached) {
    return Object.freeze({ unsigned: cached, stampPayload, calculation: immutableCalculation, appliedDefaults });
  }
  const stableUnsigned = freezeUnsigned({
    ...unsignedRaw,
    inputs: { ...unsignedRaw.inputs },
    headRef: { ...unsignedRaw.headRef },
  });
  setBoundedMemo(__unsignedCache, cacheKey, stableUnsigned);
  return Object.freeze({ unsigned: stableUnsigned, stampPayload, calculation: immutableCalculation, appliedDefaults });
}

